// One request per unique symbol. Decides whether the primary source (Yahoo) may be used:
// - simulate_down: the owner switched it off on purpose with /simulate (demo of failure handling)
// - circuit_open: Yahoo failed in 3 runs in a row, so we skip it for 30 minutes and go straight to the backup
const health = {};
for (const it of $('Read Source Health').all()) health[it.json.source] = it.json;
let symbols = $('When Called By Report').first().json.symbols;
if (typeof symbols === 'string') {
  try { symbols = JSON.parse(symbols); } catch (e) { symbols = symbols.split(','); }
}
symbols = Array.from(new Set((symbols || []).map(s => String(s).trim().toUpperCase()).filter(Boolean)));
const y = health.yahoo || {};
const av = health.alphavantage || {};
let primaryState = 'ok';
const lastChecked = y.last_checked ? new Date(y.last_checked).getTime() : 0;
const minutesSinceCheck = (Date.now() - lastChecked) / 60000;
if (y.simulate_down) primaryState = 'simulated_down';
else if ((y.consecutive_failures || 0) >= 3 && minutesSinceCheck < 30) primaryState = 'circuit_open';
const base = primaryState === 'ok' ? 'https://query1.finance.yahoo.com' : 'https://yahoo-unavailable.invalid';
return symbols.map(s => ({ json: {
  symbol: s,
  primary_state: primaryState,
  backup_simulated_down: !!av.simulate_down,
  yahoo_url: base + '/v8/finance/chart/' + encodeURIComponent(s) + '?range=5d&interval=1d'
} }));

// Turn Yahoo's reply into one clean quote, or mark it as needing the backup source.
const plan = $('Plan Quote Requests').item.json;
const r = $json || {};
const res = r.chart && r.chart.result && r.chart.result[0];
if (plan.primary_state === 'ok' && res && res.meta && typeof res.meta.regularMarketPrice === 'number') {
  const m = res.meta;
  let chg = m.regularMarketChangePercent;
  if (typeof chg !== 'number') {
    const prev = m.chartPreviousClose;
    chg = prev ? (m.regularMarketPrice - prev) / prev * 100 : null;
  }
  return { json: {
    symbol: plan.symbol, ok: true, needs_backup: false, source: 'yahoo',
    name: m.shortName || m.longName || plan.symbol,
    price: m.regularMarketPrice, change_pct: chg, currency: m.currency || 'USD',
    market_time: m.regularMarketTime ? new Date(m.regularMarketTime * 1000).toISOString() : null,
    primary_state: plan.primary_state, backup_simulated_down: plan.backup_simulated_down
  } };
}
let reason = plan.primary_state;
if (reason === 'ok') reason = r.error ? String(r.error.message || r.error.description || 'request failed').slice(0, 120) : 'no data';
return { json: {
  symbol: plan.symbol, ok: false, needs_backup: true, source: 'none', primary_error: reason,
  primary_state: plan.primary_state, backup_simulated_down: plan.backup_simulated_down
} };

// Alpha Vantage answers HTTP 200 even when it refuses (an "Information" field instead of data),
// so success is decided by the content, not the status code.
const y = $('Read Yahoo Reply').item.json;
const r = $json || {};
const g = r['Global Quote'];
const proxies = { '^GSPC': 'SPY', '^IXIC': 'QQQ', '^DJI': 'DIA' };
if (g && g['05. price']) {
  const chg = parseFloat(String(g['10. change percent'] || '').replace('%', ''));
  return { json: Object.assign({}, y, {
    ok: true, needs_backup: false, source: 'alphavantage', backup_used: true,
    name: y.name || y.symbol,
    price: parseFloat(g['05. price']), change_pct: isNaN(chg) ? null : chg, currency: 'USD',
    proxy: proxies[y.symbol] || null,
    market_time: g['07. latest trading day'] ? g['07. latest trading day'] + 'T20:00:00.000Z' : null
  }) };
}
let reason = 'no data from backup';
const info = String(r.Information || r.Note || '');
if (info) reason = /per second|sparingly|burst/i.test(info) ? 'backup busy (too many requests per second)' : 'backup daily limit reached';
else if (r.error) reason = y.backup_simulated_down ? 'simulated_down' : 'backup unreachable';
return { json: Object.assign({}, y, { ok: false, source: 'none', backup_used: true, backup_error: reason }) };

// One package for the caller: every quote plus how each source behaved in this run.
const quotes = $input.all().map(i => i.json);
const attempted = quotes.filter(q => q.primary_state !== 'circuit_open');
const backupTried = quotes.filter(q => q.backup_used);
return [{ json: {
  quotes: quotes,
  primary: {
    state: quotes.length ? quotes[0].primary_state : 'ok',
    attempted: attempted.length,
    ok: attempted.filter(q => q.source === 'yahoo').length
  },
  backup: { attempted: backupTried.length, ok: backupTried.filter(q => q.ok).length },
  checked_at: new Date().toISOString()
} }];

// A source that failed for every symbol counts one more failure in a row; any success resets the count.
// Three failures in a row opens the circuit breaker (see Plan Quote Requests).
const s = $input.first().json;
const prev = {};
for (const it of $('Read Source Health').all()) prev[it.json.source] = it.json;
const rows = [];
if (s.primary.attempted > 0) {
  const failedAll = s.primary.ok === 0;
  rows.push({
    source: 'yahoo',
    consecutive_failures: failedAll ? ((prev.yahoo && prev.yahoo.consecutive_failures) || 0) + 1 : 0,
    last_status: failedAll ? 'failing' : (s.primary.ok < s.primary.attempted ? 'partial' : 'ok'),
    last_checked: s.checked_at
  });
}
if (s.backup.attempted > 0) {
  const failedAll = s.backup.ok === 0;
  rows.push({
    source: 'alphavantage',
    consecutive_failures: failedAll ? ((prev.alphavantage && prev.alphavantage.consecutive_failures) || 0) + 1 : 0,
    last_status: failedAll ? 'failing' : 'ok',
    last_checked: s.checked_at
  });
}
return rows.map(r => ({ json: r }));
